#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    scanf("%d", &n);

    vector<int> array(n);
    for (int &value : array)
        scanf("%d", &value);

    if (n == 0) {
        printf("0\n");
        return 0;
    }

    sort(array.begin(), array.end());

    int count = 1;
    int maximum = 1;

    for (int i = 1; i < n; ++i) {
        if (array[i] == array[i - 1])
            ++count;
        else
            count = 1;

        maximum = max(maximum, count);
    }

    printf("%d\n", maximum);
    return 0;
}

